import * as THREE from 'three';
import {resolveComputerStation} from './robot-session.js';
import {stageById,parseBoard,initialRobot} from './robot-lab.js';
import {disposeToyTree} from '../world/toy-kit.js';
/** Original teal shelf-arrow toy, reused without introducing a new character. */
export function createWorkshopRobot(){const root=new THREE.Group();root.name='robot-lab.robot';const mat=color=>new THREE.MeshStandardMaterial({color,roughness:.8});const teal=mat('#648d92'),cream=mat('#fff7df'),ink=mat('#294f56');const add=(geometry,material,x,y,z)=>{const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;root.add(m);return m;};const arrow=new THREE.Shape();arrow.moveTo(0,.59);arrow.lineTo(.23,.15);arrow.lineTo(0,.25);arrow.lineTo(-.23,.15);arrow.closePath();add(new THREE.ExtrudeGeometry(arrow,{depth:.16,bevelEnabled:true,bevelSize:.025,bevelThickness:.025,bevelSegments:2,steps:1}),teal,0,0,-.08);for(const x of[-.09,.09]){const white=add(new THREE.SphereGeometry(.034,10,6),cream,x,.37,-.115);white.scale.z=.45;const eye=add(new THREE.SphereGeometry(.018,8,6),ink,x,.37,-.134);eye.scale.z=.5;const wheel=add(new THREE.CylinderGeometry(.085,.085,.12,12),ink,x,.075,0);wheel.rotation.x=Math.PI/2;}return root;}
export function createRobotBoard(stageId){
 const stage=stageById(stageId),map=parseBoard(stage),root=new THREE.Group();root.name='robot-lab.board';const materials=new Map(),mat=c=>{if(!materials.has(c))materials.set(c,new THREE.MeshStandardMaterial({color:c,roughness:.9}));return materials.get(c);};
 const at=p=>({x:p.x-(map.width-1)/2,z:p.z-(map.height-1)/2});const mesh=(g,c,x,y,z,name)=>{const m=new THREE.Mesh(g,mat(c));m.position.set(x,y,z);m.name=name??'';m.castShadow=true;m.receiveShadow=true;root.add(m);return m;};const box=(w,h,d,c,x,y,z,name)=>mesh(new THREE.BoxGeometry(w,h,d),c,x,y,z,name);
 box(map.width+.42,.25,map.height+.42,'#bf9872',0,-.26,0,'robot-lab.tray');box(map.width+.16,.1,map.height+.16,'#f3dcb0',0,-.1,0);
 for(let z=0;z<map.height;z++)for(let x=0;x<map.width;x++){const p=at({x,z});box(.94,.10,.94,(x+z)%2?'#dce5d0':'#eff0dc',p.x,-.02,p.z,`robot-lab.tile.${x}.${z}`);}
 for(const p of map.walls){const q=at(p);box(.90,.43,.90,'#96af9e',q.x,.23,q.z,'robot-lab.wall');box(.91,.07,.91,'#b9cebb',q.x,.47,q.z);}
 const parts=new Map();for(const p of map.parts){const q=at(p),m=mesh(new THREE.TorusGeometry(.18,.075,6,10),'#e1ac4e',q.x,.29,q.z,'robot-lab.part');m.rotation.x=Math.PI/2;parts.set(`${p.x},${p.z}`,m);}
 const gates=[];for(const p of map.gates){const q=at(p),g=new THREE.Group();g.name='robot-lab.gate';g.position.set(q.x,0,q.z);root.add(g);for(const x of[-.34,.34]){const m=new THREE.Mesh(new THREE.BoxGeometry(.09,.74,.10),mat('#8b888b'));m.position.set(x,.4,0);g.add(m);}for(const y of[.22,.48,.7]){const m=new THREE.Mesh(new THREE.BoxGeometry(.80,.085,.10),mat('#ce8c70'));m.position.y=y;g.add(m);}gates.push(g);}
 const switches=[];for(const p of map.switches){const q=at(p);const pad=mesh(new THREE.CylinderGeometry(.31,.35,.12,16),'#bb8874',q.x,.12,q.z,'robot-lab.switch');switches.push(pad);box(.32,.025,.09,'#fff2cd',q.x,.192,q.z);}
 const q=at(map.goal);mesh(new THREE.CylinderGeometry(.38,.41,.10,20),'#e2b952',q.x,.09,q.z,'robot-lab.goal');const star=new THREE.Shape();for(let i=0;i<10;i++){const a=i*Math.PI/5,r=i%2?.13:.28;i?star.lineTo(Math.sin(a)*r,Math.cos(a)*r):star.moveTo(0,r);}star.closePath();const starMesh=mesh(new THREE.ShapeGeometry(star),'#fff8d7',q.x,.149,q.z,'robot-lab.goal-star');starMesh.rotation.x=-Math.PI/2;
 const parcel=map.parcel?box(.40,.35,.36,'#da9876',at(map.parcel).x,.24,at(map.parcel).z,'robot-lab.parcel'):null;
 const robot=createWorkshopRobot();root.add(robot);const carry=new THREE.Mesh(new THREE.BoxGeometry(.24,.22,.22),mat('#da9876'));carry.name='robot-lab.carried-parcel';carry.position.set(0,.28,-.27);robot.add(carry);const beam=new THREE.Mesh(new THREE.ConeGeometry(.17,.43,12),new THREE.MeshBasicMaterial({color:'#e9bc59',transparent:true,opacity:.4,depthWrite:false}));beam.rotation.x=-Math.PI/2;beam.position.set(0,.19,-.39);robot.add(beam);
 let state=initialRobot(stage.id),target={x:0,z:0,yaw:0},alive=true;
 function update(next,{snap=false}={}){if(!alive)return;state=next;const p=at(next);target={...p,yaw:-next.heading*Math.PI/2};for(const[k,m]of parts)m.visible=!next.parts.includes(k);for(const g of gates)g.visible=!next.gateOpen;for(const s of switches)s.material=mat(next.gateOpen?'#6caa92':'#bb8874');carry.visible=next.carrying;beam.visible=next.phase==='running'||next.phase==='paused';if(parcel)parcel.visible=!next.carrying&&!next.delivered;if(snap){robot.position.set(p.x,.07,p.z);robot.rotation.y=target.yaw;}root.userData.stageId=next.stageId;}
 function tick(dt){if(!alive)return false;const amount=1-Math.exp(-Math.max(0,Math.min(.15,dt))*13),dx=target.x-robot.position.x,dz=target.z-robot.position.z,da=Math.atan2(Math.sin(target.yaw-robot.rotation.y),Math.cos(target.yaw-robot.rotation.y));robot.position.x+=dx*amount;robot.position.z+=dz*amount;robot.rotation.y+=da*amount;return Math.abs(dx)+Math.abs(dz)+Math.abs(da)>.0001;}
 update(state,{snap:true});return {root,robot,parts,gates,update,tick,dispose(){if(!alive)return;alive=false;const attached=new Set();root.traverse(o=>{if(o.material)attached.add(o.material);});disposeToyTree(root);for(const m of materials.values())if(!attached.has(m))m.dispose();}};
}
export function drawWorkshopMap(ctx,s){if(!ctx)return;const b=parseBoard(stageById(s.stageId)),w=ctx.canvas?.width??500,h=ctx.canvas?.height??500,pad=22,cell=Math.min((w-pad*2)/b.width,(h-pad*2)/b.height),ox=(w-cell*b.width)/2,oz=(h-cell*b.height)/2;ctx.clearRect(0,0,w,h);ctx.fillStyle='#eef0db';ctx.fillRect(0,0,w,h);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`bold ${cell*.46}px "Dormi Gentle Pen", sans-serif`;for(let z=0;z<b.height;z++)for(let x=0;x<b.width;x++){ctx.fillStyle=(x+z)%2?'#d9e4d0':'#f9f2df';ctx.fillRect(ox+x*cell,oz+z*cell,cell-2,cell-2);}const mark=(p,t,c)=>{ctx.fillStyle=c;ctx.fillText(t,ox+(p.x+.5)*cell,oz+(p.z+.5)*cell);};for(const p of b.walls){ctx.fillStyle='#8d9f91';ctx.fillRect(ox+p.x*cell+3,oz+p.z*cell+3,cell-8,cell-8);}mark(b.goal,'★','#a17a20');for(const p of b.parts)if(!s.parts.includes(`${p.x},${p.z}`))mark(p,'⚙','#b28124');for(const p of b.switches)mark(p,s.gateOpen?'✓':'●',s.gateOpen?'#377f65':'#b16b57');for(const p of b.gates)mark(p,s.gateOpen?'·':'▥',s.gateOpen?'#377f65':'#a3563e');if(b.parcel&&!s.carrying&&!s.delivered)mark(b.parcel,'箱','#a96845');ctx.save();ctx.translate(ox+(s.x+.5)*cell,oz+(s.z+.5)*cell);ctx.rotate(s.heading*Math.PI/2);ctx.fillStyle='#3e7175';ctx.beginPath();ctx.moveTo(0,-cell*.32);ctx.lineTo(cell*.26,cell*.25);ctx.lineTo(0,cell*.12);ctx.lineTo(-cell*.26,cell*.25);ctx.closePath();ctx.fill();if(s.carrying){ctx.fillStyle='#df9772';ctx.fillRect(-cell*.12,-cell*.02,cell*.24,cell*.2);}ctx.restore();}
export function frameComputerCamera(camera,{zoneRoot,station,aspect=1}){
 const resolved=resolveComputerStation(zoneRoot,station);if(!resolved)return false;const frame=resolved.camera??{},root=frame.root??resolved.fixture,span=frame.span??5;root.updateWorldMatrix(true,false);camera.position.copy(root.localToWorld(new THREE.Vector3(...(frame.position??[2.8,4.4,4.3]))));camera.lookAt(root.localToWorld(new THREE.Vector3(...(frame.target??[0,1.3,1.7]))));camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;if(aspect<1){camera.left=-3;camera.right=3;camera.top=3/aspect;camera.bottom=-3/aspect;}camera.updateProjectionMatrix();return true;
}
export function createWorkshopViewport({canvas,fallback,onFallback=()=>{},reduced=false,worldScene=null,zoneRoot=null,station=null}){
 let renderer,board,disposed=false,angle=0,top=false,computer=false,state,dirty=true;const scene=new THREE.Scene();scene.background=new THREE.Color('#e2e9d7');const camera=new THREE.OrthographicCamera(-5,5,4,-4,.1,100),computerCamera=new THREE.OrthographicCamera(-4,4,3,-3,.1,200);scene.add(new THREE.HemisphereLight('#fff9e6','#7c9884',2.8));const light=new THREE.DirectionalLight('#fff0d3',3);light.position.set(-3,8,5);scene.add(light);
 try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio??1,1.7));renderer.outputColorSpace=THREE.SRGBColorSpace;}catch{canvas.hidden=true;fallback.hidden=false;onFallback();}
 const contextLost=e=>{e.preventDefault();canvas.hidden=true;fallback.hidden=false;onFallback();if(state)drawWorkshopMap(fallback.getContext('2d'),state);};canvas.addEventListener('webglcontextlost',contextLost);
 function fit(){if(disposed||!renderer)return;const r=canvas.getBoundingClientRect(),w=Math.max(1,r.width),h=Math.max(1,r.height),size=state?parseBoard(stageById(state.stageId)).width:5;renderer.setSize(w,h,false);const span=size*1.44,aspect=w/h;camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;if(aspect<1.05){camera.left=-span*.64;camera.right=span*.64;camera.top=span*.64/aspect;camera.bottom=-span*.64/aspect;}const t=angle*Math.PI/2;camera.position.set(top?.001:Math.sin(t+.65)*9,top?12:8,top?.001:Math.cos(t+.65)*9);camera.lookAt(0,0,0);camera.updateProjectionMatrix();frameComputerCamera(computerCamera,{zoneRoot,station,aspect});dirty=true;}
 const observer=typeof ResizeObserver!=='undefined'?new ResizeObserver(fit):null;observer?.observe(canvas);
 return {update(next){if(disposed)return;const changed=state?.stageId!==next.stageId;state=next;if(changed){board?.dispose();board=createRobotBoard(next.stageId);scene.add(board.root);fit();}board.update(next,{snap:reduced||changed});drawWorkshopMap(fallback.getContext('2d'),next);dirty=true;},tick(dt){if(disposed||!board)return;dirty=board.tick(dt)||dirty;if(dirty&&renderer&&!canvas.hidden){renderer.render(computer&&worldScene?worldScene:scene,computer&&worldScene?computerCamera:camera);dirty=false;}},rotate(){angle=(angle+1)%4;fit();},top(){top=!top;fit();return top;},computer(){computer=!!worldScene&&!computer;dirty=true;return computer;},dispose(){if(disposed)return;disposed=true;observer?.disconnect();canvas.removeEventListener('webglcontextlost',contextLost);board?.dispose();renderer?.renderLists.dispose();renderer?.dispose();renderer?.forceContextLoss();},fit};
}
